    ctx.save();ctx.font='600 15px Manrope, sans-serif';ctx.textAlign='center';
    const w=ctx.measureText(label).width+24,y=point.y-172;
    ctx.fillStyle='#0d1b29ed';ctx.fillRect(point.x-w/2,y-19,w,30);
