    if(!boss.autoPhase&&Math.abs(player.x-boss.x)>165)boss.x=clamp(boss.x+Math.sign(player.x-boss.x)*(realm===1?95:realm===2?85+boss.stage*10:65)*dt,level.arena.x+60,level.arena.x+level.arena.w-boss.w-60);
