const ShadowAnimation=(()=>{
  function sample({auto=null,cast=null,release=null,idleTime=0,deathPose=null}={}){
    if(deathPose)return {...deathPose};
    if(cast?.kind==='devour')return {clip:'devour',frame:Math.min(5,Math.floor(clamp(1-cast.remaining/cast.duration,0,1)*6))};
    if(auto?.stage==='windup'){
      const progress=clamp(1-auto.remaining/(auto.duration||SHADOW_ATTACK_TIMING.meleeWindup),0,1);
      return {clip:'melee',frame:progress<.17?0:progress<.6?1:2};
    }
    const recovery=auto?.stage==='recover'?(auto.duration||SHADOW_ATTACK_TIMING.meleeRecovery)-auto.remaining:null;
    if(recovery!==null&&recovery<SHADOW_ATTACK_TIMING.meleeStrike+.12)return {clip:'melee',frame:recovery<SHADOW_ATTACK_TIMING.meleeStrike*.43?3:4};
    if(release){const progress=release.elapsed/release.duration;return {clip:'cast',frame:progress>=1?0:progress<.34?3:progress<.72?4:5};}
    if(cast?.stage==='windup'){
      const progress=clamp(1-cast.remaining/cast.duration,0,1);
      return {clip:'cast',frame:progress<.15?0:progress<.55?1:2};
    }
    if(recovery!==null)return {clip:'melee',frame:5};
    return {clip:'idle',frame:Math.floor(Math.max(0,idleTime)*3)%6};
  }
  function draw(pose,x,y,alpha=1){
    const clip=SHADOW_CLIPS[pose.clip],rect=clip?.frames[pose.frame],image=Visuals.images[clip?.image];
    if(!rect||!image?.complete||!image.naturalWidth)return;
    const sy=clip.scale,sx=sy*1.18;
    ctx.save();ctx.globalAlpha*=alpha;
    ctx.drawImage(image,rect.x,rect.y,rect.w,rect.h,x-rect.anchorX*sx,y-rect.anchorY*sy,rect.w*sx,rect.h*sy);
    ctx.restore();
  }
  return Object.freeze({sample,draw});
})();


/* prologue.js */
/* A playable nightmare. Its defeat leads to Japan, never to a shrine or boss reward. */
'use strict';
const Prologue=(()=>{
  const FLOOR=720,ARENA_LEFT=2940,ARENA_RIGHT=4230,SHADOW_X=3790,MAX_HP=100000;
  const dream=makeLevel('dream',4500,1000,{x:240,y:FLOOR});
  ledge(dream,'silent-path',0,FLOOR,4500,'ground',280);
  let phase='off',clock=0,battleTime=0,zoom=1,castIndex=0,heartbeat=0;
  let hazards=[],bolts=[],auto=null,cast=null;
  let animationTime=0,castVisual=null,deathPose=null,currentPose={clip:'idle',frame:0},previousPose=null,blendClock=.12;
  const active=()=>phase!=='off';
  function stop(){DevDamage.clear();phase='off';hazards=[];bolts=[];auto=cast=null;animationTime=0;castVisual=deathPose=previousPose=null;currentPose={clip:'idle',frame:0};blendClock=.12;$('game').classList.remove('dream-active');}
  function samplePose(){return ShadowAnimation.sample({auto,cast,release:castVisual,idleTime:reducedMotion.matches?0:animationTime,deathPose});}
  function setPose(pose){
    if(currentPose.clip!==pose.clip){previousPose={...currentPose};blendClock=0;}
    currentPose=pose;if(boss)boss.animation={...pose};
  }
  function start(){
    stop();phase='walk';clock=battleTime=castIndex=heartbeat=0;zoom=1;
    level=dream;platforms=dream.platforms.map(p=>({...p,dx:0}));enemies=[];particles=[];drops=[];projectiles=[];
    initPlayer(dream.start);player.inv=0;bossStarted=false;
    boss={x:SHADOW_X-270,y:FLOOR-440,w:460,h:440,hp:MAX_HP,max:MAX_HP,dead:false,inv:0,flash:0};
    camera=0;cameraY=FLOOR-H*.82;state='play';keys.clear();pressed.clear();
    $('game').classList.add('dream-active');showHUD(true);hud();
  }
  function hud(){
    $('realmLabel').textContent=I18n.t('prologue.label');$('questLabel').textContent=I18n.t('prologue.label');
    $('kibaCurrent').textContent=I18n.t('prologue.energy');$('areaLabel').textContent=I18n.t('prologue.place');
    $('health').innerHTML='<span>♥</span>'.repeat(player.hp)+'<span class="empty">♥</span>'.repeat(player.maxHp-player.hp);
    $('health').setAttribute('aria-label',I18n.format('message.arg0.of.arg1.health',[player.hp,player.maxHp]));
    $('dashHint').hidden=true;$('dropHint').hidden=true;
    $('jumpHint').textContent=I18n.t('text.jump.4e09c3');
    $('objective').textContent=I18n.t(phase==='walk'?'prologue.objective.walk':'prologue.objective.battle');
    $('bossHud').hidden=!['reveal','battle'].includes(phase);$('bossName').textContent=I18n.t('prologue.boss');
    $('bossHealth').style.width=(boss.hp/boss.max*100)+'%';
    $('bossHealth').parentElement?.setAttribute('aria-label',I18n.format('prologue.boss.health',[boss.hp,boss.max]));
    let warning=cast?.stage==='windup'?'prologue.warning.'+cast.kind:auto?.stage==='windup'?'prologue.warning.sweep':null;
    if(phase==='reveal')warning='prologue.warning.arrival';
    $('prompt').hidden=!warning;if(warning)$('prompt').textContent=I18n.t(warning);
  }
  function reveal(){
    phase='reveal';clock=0;player.vx=0;keys.clear();pressed.clear();bossStarted=true;
    tone(45,2,'sine',.035);
  }
  function lose(){
    if(!active()||['death','awakening'].includes(phase))return;
    deathPose=samplePose();setPose(deathPose);
    phase='death';clock=0;const before=player.hp;player.hp=0;DevDamage.record('incoming',player,before,player.hp);player.vx=player.vy=0;attack=dash=0;
    keys.clear();pressed.clear();hazards=[];bolts=[];auto=cast=castVisual=null;shake=.25;
    burst(player.x+21,player.y+30,'#bd91df',35);showHUD(false);$('bossHud').hidden=true;$('prompt').hidden=true;
    tone(48,1.5,'sawtooth',.025);
  }
  function hurt(amount,unavoidable=false){
    if(DevImmortality.active)return;
    if(phase!=='battle'||!unavoidable&&player.inv>0)return;
    const before=player.hp;player.hp=Math.max(0,player.hp-amount);DevDamage.record('incoming',player,before,player.hp);player.inv=1.15;shake=reducedMotion.matches?0:.15;
    burst(player.x+21,player.y+30,'#d6a4f5',18);tone(80,.25,'sawtooth',.03);
    if(!player.hp)lose();else hud();
  }
  function hit(amount,box){
    if(phase!=='battle'||boss.inv>0||box&&!overlap(box,boss)||!Number.isFinite(amount)||amount<=0)return false;
    // A normal sword can harm the apparition, but cannot end this story encounter.
    const before=boss.hp;boss.hp=Math.max(1,boss.hp-Math.min(amount,playerAttackDamage()));DevDamage.record('outgoing',boss,before,boss.hp);boss.inv=.28;boss.flash=.2;
    burst(Math.min(boss.x+50,player.x+130),player.y+28,'#d9b3f8',14);tone(145,.1,'triangle',.02);return true;
  }
  function hazard(kind,x,y,w,h,warning,life,amount){hazards.push({kind,x,y,w,h,warning,life,amount,active:false});}
  function releaseCast(kind){
    if(kind!=='devour')castVisual={kind,elapsed:0,duration:SHADOW_ATTACK_TIMING.spellRelease};
    if(kind==='bolts'){
      const x=SHADOW_X-150,y=FLOOR-300,a=Math.atan2(player.y+30-y,player.x+21-x);
      for(const offset of [-.22,0,.22])bolts.push({x,y,vx:Math.cos(a+offset)*420,vy:Math.sin(a+offset)*420,life:5,radius:17,damage:5,color:'#c598ff',kind:'shadowBolt'});
    }else if(kind==='rifts'){
      for(const d of [-2,-1,0,1,2])hazard('rift',clamp(player.x+d*155,ARENA_LEFT+20,ARENA_RIGHT-100),FLOOR-230,85,230,.8+Math.abs(d)*.12,1.1,8);
    }else if(kind==='storm'){
      for(let i=0;i<7;i++)hazard('storm',ARENA_LEFT+60+i*170,160,70,FLOOR-160,.65+i*.1,.65,7);
    }else if(kind==='wave'){
      bolts.push({x:ARENA_RIGHT-30,y:FLOOR-38,vx:-520,vy:0,life:4,radius:34,damage:6,color:'#d4b3fc',kind:'wave'});
    }else if(kind==='devour'){
      // The black hole engulfs the whole arena, including airborne Momo and invulnerability frames.
      hurt(player.hp+100,true);return;
    }
    tone(90,.55,'triangle',.025);
  }
  function combat(dt){
    battleTime+=dt;
    if(battleTime>=28&&cast?.kind!=='devour'&&!hazards.some(h=>h.kind==='sweep'&&h.life>0)){
      cast={kind:'devour',stage:'windup',remaining:SHADOW_ATTACK_TIMING.devourWindup,duration:SHADOW_ATTACK_TIMING.devourWindup};auto=null;
      hazard('devour',ARENA_LEFT,0,ARENA_RIGHT-ARENA_LEFT,FLOOR,SHADOW_ATTACK_TIMING.devourWindup,.5,100);
    }
    if(cast?.kind!=='devour'){
      if(!auto)auto={stage:'wait',remaining:.8};
      auto.remaining-=dt;
      if(auto.remaining<=0){
        if(auto.stage==='wait')auto={stage:'windup',remaining:SHADOW_ATTACK_TIMING.meleeWindup,duration:SHADOW_ATTACK_TIMING.meleeWindup,targetX:player.x+21};
        else if(auto.stage==='windup'){
          hazard('sweep',auto.targetX-210,FLOOR-135,420,135,0,SHADOW_ATTACK_TIMING.meleeStrike,4);auto={stage:'recover',remaining:SHADOW_ATTACK_TIMING.meleeRecovery,duration:SHADOW_ATTACK_TIMING.meleeRecovery,targetX:auto.targetX};
          tone(60,.3,'sawtooth',.025);
        }else auto={stage:'wait',remaining:.6};
      }
    }
    if(!cast)cast={stage:'wait',remaining:1.1};
    cast.remaining-=dt;
    if(cast.remaining<=0){
      if(cast.stage==='wait'){
        const kind=['bolts','rifts','storm','wave'][castIndex++%4];cast={kind,stage:'windup',remaining:SHADOW_ATTACK_TIMING.spellWindup,duration:SHADOW_ATTACK_TIMING.spellWindup};
      }else if(cast.stage==='windup'){const kind=cast.kind;releaseCast(kind);if(phase!=='battle')return;cast={stage:'wait',remaining:1.7};}
    }
    for(const h of hazards){
      if(h.warning>0){h.warning-=dt;if(h.warning<=0){h.active=true;shake=reducedMotion.matches?0:.08;}}
      else{h.active=true;h.life-=dt;}
      if(h.active&&h.life>0&&overlap(player,h))hurt(h.amount);
      if(phase!=='battle')return;
    }
    hazards=hazards.filter(h=>h.life>0);
    for(const p of bolts){
      p.life-=dt;const x=p.x,y=p.y;p.x+=p.vx*dt;p.y+=p.vy*dt;
      if(overlap(player,{x:Math.min(x,p.x)-p.radius,y:Math.min(y,p.y)-p.radius,w:Math.abs(p.x-x)+p.radius*2,h:Math.abs(p.y-y)+p.radius*2})){hurt(p.damage);p.life=0;}
      if(phase!=='battle')return;
    }
    bolts=bolts.filter(p=>p.life>0);
    heartbeat-=dt;if(heartbeat<=0){tone(46,.18,'sine',.025);heartbeat=.85;}
  }
  function scream(){
    if(!sound)return;
    try{
      audio ||= new (window.AudioContext||window.webkitAudioContext)();
      for(const offset of [0,.26]){
        const o=audio.createOscillator(),g=audio.createGain(),at=audio.currentTime+offset;
        o.type='sawtooth';o.frequency.setValueAtTime(510+offset*500,at);o.frequency.linearRampToValueAtTime(950,at+.17);o.frequency.exponentialRampToValueAtTime(340,at+.85);
        g.gain.setValueAtTime(.001,at);g.gain.linearRampToValueAtTime(.018,at+.14);g.gain.exponentialRampToValueAtTime(.001,at+.95);
        o.connect(g);g.connect(audio.destination);o.start(at);o.stop(at+1);
      }
    }catch{}
  }
  function wake(){
    stop();enterRealm(0);state='play';showHUD(true);persist();scream();
    story(I18n.t('prologue.wake.label'),I18n.t('prologue.wake.title'),I18n.t('prologue.wake.story'));
  }
  function update(dt){
    clock+=dt;
    animationTime+=dt;blendClock=Math.min(.12,blendClock+dt);
    if(castVisual){castVisual.elapsed+=dt;if(castVisual.elapsed>=castVisual.duration+SHADOW_ATTACK_TIMING.spellRecovery)castVisual=null;}
    if(phase==='death'){if(clock>=2.6){phase='awakening';clock=0;scream();}return;}
    if(phase==='awakening'){if(clock>=4.3)wake();return;}
    boss.inv=Math.max(0,boss.inv-dt);boss.flash=Math.max(0,boss.flash-dt);
    if(phase==='reveal'){
      if(clock>=2.8){phase='battle';clock=0;player.inv=.6;keys.clear();pressed.clear();}
    }else{
      input(dt);if(state!=='play')return;movePlayer(dt);advanceSwordAttack(dt);
      if(phase==='walk'&&player.x>=3100)reveal();
      else if(phase==='battle'){player.x=clamp(player.x,ARENA_LEFT+25,ARENA_RIGHT-player.w-25);combat(dt);}
    }
    for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=350*dt;}particles=particles.filter(p=>p.life>0);
    const targetZoom=phase==='walk'?1:Math.min(1,viewW/1280);
    zoom+=(targetZoom-zoom)*Math.min(1,dt*3);
    const targetX=phase==='walk'?clamp(player.x-viewW*.38,0,dream.width-viewW):ARENA_LEFT-35;
    camera+=(targetX-camera)*Math.min(1,dt*4);cameraY=FLOOR-H*.82/zoom;
    boss.move=cast?.kind||null;boss.autoPhase=auto?.stage||null;boss.hazards=hazards;boss.projectiles=bolts;
    setPose(samplePose());
    if(['walk','reveal','battle'].includes(phase))hud();
  }
  function cover(image,alpha=1){
    if(!image?.complete||!image.naturalWidth)return;
    const s=Math.max(viewW/image.naturalWidth,H/(image.naturalHeight||image.naturalWidth));
    ctx.save();ctx.globalAlpha=alpha;ctx.drawImage(image,(viewW-image.naturalWidth*s)/2,(H-(image.naturalHeight||image.naturalWidth)*s)/2,image.naturalWidth*s,(image.naturalHeight||image.naturalWidth)*s);ctx.restore();
  }
  function fog(x,y,w,h,alpha=.2){
    const g=ctx.createRadialGradient(x,y,1,x,y,w);g.addColorStop(0,'#b999d6');g.addColorStop(1,'#35214600');
    ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(x,y,w,h,0,0,Math.PI*2);ctx.fill();ctx.restore();
  }
  function blackHole(){
    const y=FLOOR-295;ctx.save();ctx.translate(SHADOW_X,y);
    const halo=ctx.createRadialGradient(0,0,60,0,0,415);halo.addColorStop(0,'#010106');halo.addColorStop(.62,'#08040e');halo.addColorStop(.8,'#58357b99');halo.addColorStop(1,'#25103400');
    ctx.fillStyle=halo;ctx.fillRect(-425,-425,850,850);
    ctx.fillStyle='#010106';ctx.beginPath();ctx.ellipse(0,0,237,285,0,0,Math.PI*2);ctx.fill();
    for(let i=0;i<6;i++){
      ctx.save();ctx.rotate((reducedMotion.matches?0:time*.065)+i*.35);ctx.strokeStyle=i%2?'#ac7ddd55':'#58367888';ctx.lineWidth=i===0?4:1.5;
      ctx.beginPath();ctx.ellipse(0,0,250+i*17,285+i*9,0,.2,Math.PI*1.72);ctx.stroke();ctx.restore();
    }
    ctx.restore();
  }
  function apparition(){
    if(phase==='walk')return;
    const appear=phase==='reveal'?clamp(clock/2.4,0,1):1;
    const bob=reducedMotion.matches||currentPose.clip!=='idle'?0:Math.sin(animationTime*.7)*3;
    const x=SHADOW_X+20,y=FLOOR-385+bob;
    ctx.save();ctx.globalAlpha=appear*.9;
    if(previousPose&&blendClock<.12){
      const blend=blendClock/.12;ShadowAnimation.draw(previousPose,x,y,1-blend);ShadowAnimation.draw(currentPose,x,y,blend);
    }else ShadowAnimation.draw(currentPose,x,y);
    if(boss.flash>0){fog(SHADOW_X,FLOOR-350,230,260,boss.flash*.4);}
    ctx.restore();
    for(let i=0;i<13;i++){
      const drift=reducedMotion.matches?0:Math.sin(time*.5+i)*60;
      fog(SHADOW_X-360+i*57+drift,FLOOR-85+Math.sin(i)*45,155,65,appear*.2);
    }
  }
  function drawHazards(){
    if(auto?.stage==='recover'&&auto.remaining>auto.duration-SHADOW_ATTACK_TIMING.meleeStrike){
      const progress=(auto.duration-auto.remaining)/SHADOW_ATTACK_TIMING.meleeStrike;
      BossVFX.slash('slashShadow',auto.targetX,FLOOR-80,420,145,-1,progress);
    }
    for(const h of hazards){
      if(h.kind==='devour')BossVFX.devour(h);
      else if(h.kind!=='sweep')BossVFX.column(h);
    }
    if(auto?.stage==='windup'){
      ctx.save();ctx.strokeStyle='#e6c1ff';ctx.lineWidth=3;ctx.setLineDash([12,7]);ctx.beginPath();ctx.ellipse(auto.targetX,FLOOR-8,205,20,0,0,Math.PI*2);ctx.stroke();ctx.restore();
    }
    for(const p of bolts)Visuals.projectile(p);
  }
  function awakening(){
    cover(Visuals.images.momoRoom);ctx.fillStyle='#09131933';ctx.fillRect(0,0,viewW,H);
    const feet=H*.76,size=Math.min(170,viewW*.35),mx=viewW*.34;
    ctx.fillStyle='#09131955';ctx.beginPath();ctx.ellipse(mx,feet,size*.35,9,0,0,Math.PI*2);ctx.fill();
    if(clock<2.25&&menuSheet.complete&&menuSheet.naturalWidth)ctx.drawImage(menuSheet,1024,512,512,512,mx-size/2,feet-450*size/512,size,size);
    else drawMomo(mx,feet,size*.85,0,0,1);
    const shade=clamp(1-clock/1.6,0,1);ctx.fillStyle=`rgba(0,0,0,${shade})`;ctx.fillRect(0,0,viewW,H);
    caption(I18n.t(clock<2?'prologue.awakening.dream':'prologue.awakening.screams'),H*.14,true);
  }
  function caption(text,y,dawn=false){
    ctx.save();ctx.textAlign='center';
    const size=Math.min(24,Math.max(16,viewW*.035)),width=Math.min(660,viewW-36),maxText=width-36;
    ctx.font=`600 ${size}px Manrope, sans-serif`;
    const lines=[];let line='';
    for(const word of text.split(/\s+/)){const next=line?line+' '+word:word;const measured=ctx.measureText(next)?.width??next.length*size*.55;if(line&&measured>maxText){lines.push(line);line=word;}else line=next;}if(line)lines.push(line);
    if(dawn){
      ctx.fillStyle='#132a32ed';ctx.fillRect((viewW-width)/2,y-38,width,lines.length*(size+9)+48);
      ctx.strokeStyle='#d9ba7b99';ctx.lineWidth=1;ctx.strokeRect((viewW-width)/2,y-38,width,lines.length*(size+9)+48);
      ctx.fillStyle='#d9ba7b';ctx.font='600 11px Manrope, sans-serif';ctx.fillText(I18n.t('prologue.wake.label'),viewW/2,y-15,maxText);ctx.font=`600 ${size}px Manrope, sans-serif`;
    }
    lines.forEach((value,index)=>{const baseline=y+16+index*(size+9);if(!dawn){ctx.strokeStyle='#070b16';ctx.lineWidth=5;ctx.strokeText(value,viewW/2,baseline);}ctx.fillStyle=dawn?'#f2e6cc':'#efddff';ctx.fillText(value,viewW/2,baseline);});
    ctx.restore();
  }
  function draw(){
    ctx.fillStyle='#03040b';ctx.fillRect(0,0,viewW,H);
    if(phase==='awakening'){awakening();return;}
    cover(Visuals.images.shadowBackdrop,.8);
    const dim=ctx.createLinearGradient(0,0,0,H);dim.addColorStop(0,'#08051277');dim.addColorStop(.65,'#100d2044');dim.addColorStop(1,'#02050ed9');ctx.fillStyle=dim;ctx.fillRect(0,0,viewW,H);
    ctx.save();ctx.scale(zoom,zoom);ctx.translate(-camera,-cameraY);
    blackHole();apparition();
    ctx.fillStyle='#0b101c';ctx.fillRect(camera-100,FLOOR,viewW/zoom+200,400);
    ctx.save();ctx.filter='grayscale(1) brightness(.4)';Visuals.terrain(realms[1],platforms);ctx.restore();
    for(let i=0;i<14;i++){
      const drift=reducedMotion.matches?0:Math.sin(time*.23+i)*55;
      fog(camera+i*140+drift,FLOOR+8,180,32,.14);
    }
    drawHazards();
    for(const p of particles){ctx.globalAlpha=clamp(p.life*2,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);}ctx.globalAlpha=1;
    if(phase==='death'){
      ctx.save();ctx.translate(player.x+21,player.y+55);ctx.rotate(Math.min(clock,1)*Math.PI*.45);ctx.globalAlpha=clamp(1-clock/2,0,1);drawMomo(0,12,96,0,0,player.face);ctx.restore();
    }else drawPlayer();
    DevDamage.draw();
    ctx.restore();
    if(phase==='death'){ctx.fillStyle=`rgba(1,1,6,${clamp(clock/2.1,0,1)})`;ctx.fillRect(0,0,viewW,H);caption(I18n.t('prologue.death'),H*.48);}
  }
  function village(){
    if(realm!==0||camera>1700)return;
    for(const x of [680,1130,1450]){
      for(let i=0;i<5;i++)fog(x+(reducedMotion.matches?0:Math.sin(time*.3+i)*23),1000-70-i*50,60+i*22,50,.14);
      for(let i=0;i<7;i++){
        const t=reducedMotion.matches?.5:(time*.25+i*.13)%1;ctx.save();ctx.globalAlpha=(1-t)*.6;ctx.fillStyle='#e6a176';ctx.fillRect(x+Math.sin(i*19)*45,985-t*145,3,5);ctx.restore();
      }
    }
  }
  return Object.freeze({start,stop,update,draw,hud,hit,hurt,lose,wake,village,get active(){return active();},get phase(){return phase;}});
})();


/* inventory.js */
/* Inventory is a view of persistent quest flags; opening it never writes a save. */
'use strict';
const Inventory=(()=>{
 let initialized=false,returnFocus=null,selected=null;
 const catalogue=ART_INVENTORY.items,ids=Object.keys(catalogue);
 function quantity(id){const item=catalogue[id];if(!item)return 0;if(item.stack)return Merchant.stock(id);return flags[item.realm].includes(id)&&!(item.consumedBy&&flags[item.consumedBy.realm].includes(item.consumedBy.id))?1:0;}
 function contents(){return ids.filter(id=>quantity(id)>0);}
 function image(canvas,image,rect,size){
  const ratio=size?Math.max(1,Math.min(3,window.devicePixelRatio||1)):1;
  if(size){canvas.width=Math.round(size.w*ratio);canvas.height=Math.round(size.h*ratio);}
  const c=canvas.getContext('2d');c.globalAlpha=1;c.globalCompositeOperation='source-over';c.filter='none';c.clearRect(0,0,canvas.width,canvas.height);
  if(!image?.complete||!image.naturalWidth)return;
  c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';
  const pad=8*ratio,s=Math.min((canvas.width-pad*2)/rect.w,(canvas.height-pad*2)/rect.h),w=rect.w*s,h=rect.h*s;
  c.drawImage(image,rect.x||0,rect.y||0,rect.w,rect.h,(canvas.width-w)/2,(canvas.height-h)/2,w,h);
 }
 function equipmentArt(){
  image($('inventoryMomo'),Visuals.images.inventoryMomoPortrait,ART_INVENTORY.momo,{w:384,h:416});
  image($('inventoryWeaponArt'),Visuals.images.inventoryKatana,ART_INVENTORY.katana,{w:108,h:144});
 }
 function itemIcon(id){
  const canvas=document.createElement('canvas');canvas.className='inventory-icon';canvas.setAttribute('aria-hidden','true');
  image(canvas,Visuals.images[catalogue[id].image],catalogue[id],{w:112,h:112});
  return canvas;
 }
 function weaponName(){return I18n.t(defeated[1]?'item.dawnblade':'inventory.weapon.sword');}
 function details(id){
  $('inventoryDetailName').textContent=id==='weapon'?weaponName():id?I18n.t(catalogue[id].name):I18n.t('inventory.empty.title');
  $('inventoryDetailType').textContent=I18n.t(id==='weapon'?'inventory.type.equipped':id&&catalogue[id].stack?'inventory.type.consumable':id&&catalogue[id].category==='travelGear'?'inventory.type.travelGear':id?'inventory.type.quest':'inventory.type.backpack');
  $('inventoryDetailText').textContent=id==='weapon'?I18n.format('inventory.weapon.description',[playerAttackDamage('normal'),playerAttackDamage('heavy')]):id?Merchant.description(id):I18n.t('inventory.empty.body');
  $('inventoryQuantity').hidden=!id||!catalogue[id]?.stack;
  $('inventoryQuantity').textContent=id&&catalogue[id]?.stack?I18n.format('merchant.quantity',[quantity(id)]):'';
  $('useInventoryItem').hidden=id!=='roastMeat'&&id!=='tea';$('useInventoryItem').disabled=id==='tea'?!Merchant.canDrink():!quantity(id);
  $('useInventoryItem').textContent=I18n.t(id==='tea'?'merchant.drink':'merchant.eat');
  $('assignQuickHeal').hidden=!['roastMeat','tea'].includes(id);$('assignQuickHeal').disabled=id===quickHeal||!quantity(id);
  $('assignQuickHeal').textContent=I18n.t('merchant.quick.assign');
  $('inventoryQuickHeal').textContent=I18n.format('merchant.quick.selected',[bindingKeyLabel(Bindings.read('useMeat')[0])+' · '+I18n.t('item.'+quickHeal)+' ×'+Merchant.stock(quickHeal)]);
 }
 function choose(id){selected=id;for(const button of document.querySelectorAll('#inventory [data-inventory-item]'))button.setAttribute('aria-pressed',String(button.dataset.inventoryItem===id));details(id);}
 function render(){
  const items=contents(),active=document.activeElement?.dataset?.inventoryItem,useFocused=document.activeElement?.id==='useInventoryItem',assignFocused=document.activeElement?.id==='assignQuickHeal';
  const labels={inventoryTitle:'inventory.title',inventoryPaused:'inventory.paused',inventoryBagTitle:'inventory.bag.title',inventoryCapacity:'inventory.capacity',inventoryEquipmentTitle:'inventory.equipment.title',inventoryWeaponLabel:'inventory.weapon.slot',inventoryEquipped:'inventory.equipped',closeInventory:'inventory.close'};
  for(const [id,key] of Object.entries(labels))$(id).textContent=I18n.t(key);
  $('inventoryButton').setAttribute('aria-label',I18n.t('inventory.open'));
  $('inventoryButton').title=`${I18n.t('inventory.open')} (${bindingKeyLabel(Bindings.read('inventory')[0])})`;
  $('inventoryMomo').setAttribute('aria-label',I18n.t('inventory.character'));
  equipmentArt();
  $('inventoryCount').textContent=I18n.format('inventory.count',[items.length]);
  const grid=$('inventoryGrid');grid.replaceChildren();
  for(const id of items){
   const button=document.createElement('button');button.type='button';button.className='inventory-item';button.dataset.inventoryItem=id;
   const label=document.createElement('span');label.textContent=I18n.t(catalogue[id].name);button.append(itemIcon(id),label);
   if(catalogue[id].stack){const count=document.createElement('span');count.className='inventory-quantity';count.textContent='×'+quantity(id);button.append(count);button.setAttribute('aria-label',I18n.t(catalogue[id].name)+' · '+I18n.format('merchant.quantity',[quantity(id)]));}
   button.addEventListener('click',()=>choose(id));grid.append(button);
  }
  $('inventoryEmpty').hidden=items.length>0;$('inventoryEmpty').textContent=I18n.t('inventory.empty.title');
  $('inventoryWeaponName').textContent=weaponName();$('inventoryWeapon').setAttribute('aria-label',I18n.format('inventory.weapon.label',[weaponName()]));
  choose(selected==='weapon'||items.includes(selected)?selected:items[0]||null);
  if(useFocused&&['roastMeat','tea'].includes(selected)&&!$('useInventoryItem').disabled)$('useInventoryItem').focus();
  else if(active||useFocused||assignFocused){const next=document.querySelector(`#inventory [data-inventory-item="${active||selected}"]`)||document.querySelector(`#inventory [data-inventory-item="${selected}"]`);(next||$('closeInventory')).focus();}
 }
 function open(){
  if(state!=='play'||!player)return false;
  returnFocus=document.activeElement;keys.clear();pressed.clear();state='inventory';render();$('inventory').hidden=false;$('closeInventory').focus();return true;
 }
 function close(){
  if(state!=='inventory')return false;
  $('inventory').hidden=true;state='play';keys.clear();pressed.clear();
  if(returnFocus?.isConnected&&typeof returnFocus.focus==='function')returnFocus.focus();else $('inventoryButton').focus();return true;
 }
 function init(){
  if(initialized)return;initialized=true;
  $('inventoryButton').onclick=open;$('closeInventory').onclick=close;$('inventoryWeapon').onclick=()=>choose('weapon');
  $('useInventoryItem').onclick=()=>{if(state!=='inventory')return;if(selected==='roastMeat')Merchant.eat(true);else if(selected==='tea')Merchant.drink(true);};
  $('assignQuickHeal').onclick=()=>Merchant.selectQuick(selected);
  $('inventory').addEventListener('keydown',event=>{
   if(event.key!=='Tab'||state!=='inventory')return;
   const nodes=[...$('inventory').querySelectorAll('button:not([disabled]),[tabindex="0"]')].filter(node=>!node.hidden&&node.getClientRects().length);
   if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];
   if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
   else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
  });
  const repaint=()=>{if(state==='inventory')render();};Visuals.ready.then(repaint);
  window.addEventListener('resize',()=>{if(state==='inventory')render();});
 }
 return Object.freeze({init,open,close,render,contents,quantity,itemIcon});
})();


/* merchant.js */
/* Akash's shop and consumables share the persistent currency and item flags. */
'use strict';
const Merchant=(()=>{
 const catalogue=Object.freeze({
  roastMeat:Object.freeze({price:10,stack:true}),
  tea:Object.freeze({price:25,stack:true}),
  compass:Object.freeze({price:220}),
  minimap:Object.freeze({price:360})
 });
 const rewards=Object.freeze({enemy:5,miniboss:20,boss:50});
 let initialized=false,returnFocus=null,renderId=0,teaElapsed=0,teaPulses=0;
 const rescued=()=>flags[1].includes('akashRescued');
 const stock=id=>id==='roastMeat'?meatCount:id==='tea'?teaCount:flags[1].includes(id)?1:0;
 function selectAvailable(){if(!stock(quickHeal)){const other=quickHeal==='tea'?'roastMeat':'tea';if(stock(other))quickHeal=other;}}
 function selectQuick(id){
  if(state!=='inventory'||!['roastMeat','tea'].includes(id)||!stock(id))return false;
  quickHeal=id;persist();Inventory.render();return true;
 }
 function useQuick(){if(state!=='play'||Prologue.active||!player||player.hp<=0)return false;selectAvailable();return quickHeal==='tea'?drink():eat();}
 function addStock(id){
  if(!catalogue[id]?.stack||stock(id)>=Number.MAX_SAFE_INTEGER)return false;
  if(id==='roastMeat')meatCount++;else if(id==='tea')teaCount++;else return false;
  selectAvailable();
  return true;
 }
 const vendor=()=>forestCamp.npcs.find(n=>n.id==='akash');
 const nearVendor=()=>level===forestCamp&&rescued()&&pointNear(vendor(),95,85);
 function award(amount){
  if(!Number.isSafeInteger(amount)||amount<0)throw Error('Invalid coin reward');
  const gained=Math.min(amount,Number.MAX_SAFE_INTEGER-coins);coins+=gained;return gained;
 }
 function free(){
  if(state!=='play'||level!==yomi||rescued()||!pointNear(yomi.akash,100,85))return false;
  if(enemies.some(e=>e.group==='akash'&&!e.dead)){toast(I18n.t('merchant.guards'));return false;}
  flags[1].push('akashRescued');persist();updateHUD();
  story(I18n.t('merchant.name'),I18n.t('camp.name'),I18n.t('merchant.rescue.story'));return true;
 }
 function description(id){return ['roastMeat','tea'].includes(id)?I18n.format('inventory.description.'+id,[bindingKeyLabel(Bindings.read('useMeat')[0])]):I18n.t('inventory.description.'+id);}
 function purchase(id){
  if(state!=='shop'||$('shop').hidden||!nearVendor()||!Object.hasOwn(catalogue,id))return false;
  const product=catalogue[id];
  if(!product.stack&&stock(id))return false;
  if(coins<product.price||product.stack&&stock(id)===Number.MAX_SAFE_INTEGER)return false;
  coins-=product.price;if(product.stack)addStock(id);else flags[1].push(id);
  persist();updateHUD();render();$('shopStatus').textContent=I18n.t('merchant.purchased');return true;
 }
 function eat(fromInventory=false){
  if(Prologue.active||!player||player.hp<=0||!meatCount||state!==(fromInventory?'inventory':'play'))return false;
  const delta=Math.random()<2/3?2:-1,before=player.hp;
  meatCount--;selectAvailable();player.hp=Math.max(1,Math.min(player.maxHp,player.hp+delta));
  persist();updateHUD();
  toast(player.hp>before?I18n.format('message.arg0.of.arg1.health',[player.hp,player.maxHp]):I18n.t(player.hp<before?'merchant.health.down':'merchant.health.same'));
  if(fromInventory)Inventory.render();return true;
 }
 function canDrink(){return !Prologue.active&&!!player&&player.hp>0&&player.hp<player.maxHp&&teaCount>0&&teaPulses===0;}
 function drink(fromInventory=false){
  if(state!==(fromInventory?'inventory':'play')||!canDrink())return false;
  teaCount--;selectAvailable();teaElapsed=0;teaPulses=3;persist();updateHUD();if(fromInventory)Inventory.render();toast(I18n.t('merchant.tea.started'));return true;
 }
 function resetTea(){teaElapsed=0;teaPulses=0;}
 function update(dt){
  if(state!=='play'||Prologue.active||!player||player.hp<=0||!teaPulses||!Number.isFinite(dt)||dt<=0)return;
  teaElapsed+=dt;
  while(teaPulses&&teaElapsed+1e-9>=2){teaElapsed=Math.max(0,teaElapsed-2);teaPulses--;player.hp=Math.min(player.maxHp,player.hp+1);updateHUD();}
  if(!teaPulses)teaElapsed=0;
 }
 function render(){
  const token=++renderId,focus=document.activeElement?.id;
  $('shopTitle').textContent=I18n.t('merchant.shop.title');$('shopIntro').textContent=I18n.t('merchant.greeting');
  $('shopCoins').textContent=I18n.t('merchant.coins')+': '+coins;
  $('closeShop').textContent=I18n.t('inventory.close');$('shopStatus').textContent='';
  const grid=$('shopItems');grid.replaceChildren();
  for(const [id,product]of Object.entries(catalogue)){
   const card=document.createElement('section');card.className='shop-item';
   if(Object.hasOwn(ART_INVENTORY.items,id))card.append(Inventory.itemIcon(id));
   const name=document.createElement('h3');name.textContent=I18n.t('item.'+id);
   const body=document.createElement('p');body.textContent=description(id);
   const button=document.createElement('button');button.id='buy-'+id;button.type='button';
   const owned=!product.stack&&stock(id)>0;
   button.disabled=!!owned||coins<product.price||product.stack&&stock(id)===Number.MAX_SAFE_INTEGER;
   button.textContent=owned?I18n.t('merchant.owned'):I18n.format('merchant.buy',[product.price]);
   button.onclick=()=>token===renderId&&purchase(id);card.append(name,body,button);grid.append(card);
  }
  if(focus){const next=document.getElementById(focus);if(next&&!next.disabled)next.focus();else if(focus.startsWith('buy-'))$('closeShop').focus();}
 }
 function open(){
  if(state!=='play'||!nearVendor())return false;
  returnFocus=document.activeElement;keys.clear();pressed.clear();state='shop';$('shop').hidden=false;render();$('shop').querySelector('.shop-panel').scrollTop=0;$('shopTitle').focus({preventScroll:true});return true;
 }
 function close(){
  if(state!=='shop')return false;
  renderId++;$('shop').hidden=true;state='play';keys.clear();pressed.clear();
  if(returnFocus?.isConnected)returnFocus.focus();else $('pauseButton').focus();return true;
 }
 function init(){
  if(initialized)return;initialized=true;$('closeShop').onclick=close;
  $('shop').addEventListener('keydown',event=>{
   if(state!=='shop'||event.key!=='Tab')return;
   const nodes=[...$('shop').querySelectorAll('button:not([disabled])')].filter(node=>node.getClientRects().length);
   const first=nodes[0],last=nodes.at(-1);if(!first)return;
   if(event.shiftKey&&(document.activeElement===first||!nodes.includes(document.activeElement))){event.preventDefault();last.focus();}
   else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
  });
  I18n.onChange(()=>{if(state==='shop')render();});
 }
 function drawMinimap(){
  const box=$('minimap'),visible=!!player&&stock('minimap')>0&&!Prologue.active&&!['menu','won'].includes(state)&&!DevTools.menuBackground&&!(state==='help'&&helpOrigin==='menu');
  box.hidden=!visible;if(!visible||state!=='play')return;
  box.setAttribute('aria-label',I18n.t('item.minimap'));
  const canvas=$('minimapCanvas'),w=220,h=140,dpr=Math.max(1,Math.min(3,window.devicePixelRatio||1));
  if(canvas.width!==w*dpr||canvas.height!==h*dpr){canvas.width=w*dpr;canvas.height=h*dpr;}
  const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);
  c.fillStyle='#101d29';c.fillRect(0,0,w,h);
  const scale=w/1100,X=x=>w/2+(x-player.x-player.w/2)*scale,Y=y=>h/2+(y-player.y-player.h)*scale;
  c.save();c.beginPath();c.rect(3,3,w-6,h-6);c.clip();
  c.strokeStyle='#d8c7a2';c.lineWidth=3;c.beginPath();
  for(const p of level.platforms){if(p.unmapped||p.secretArea&&!secretKnown(p.secretArea))continue;c.moveTo(X(p.x),Y(p.y));c.lineTo(X(p.x+p.w),Y(p.y));}c.stroke();
  c.fillStyle='#8ad8df';
  for(const rest of level.rests)if(visitedRests[realm].includes(rest.id)){c.beginPath();c.arc(X(rest.x),Y(rest.y),4,0,Math.PI*2);c.fill();}
  c.fillStyle='#ffcb74';c.strokeStyle='#fff';c.lineWidth=2;c.beginPath();c.arc(w/2,h/2,4,0,Math.PI*2);c.fill();c.stroke();c.restore();
 }
 return Object.freeze({init,open,close,render,free,purchase,eat,drink,canDrink,update,resetTea,addStock,selectQuick,useQuick,award,stock,description,catalogue,rewards,rescued,drawMinimap});
})();


/* compass.js */
/* A readable bearing to the current main objective, never a pathfinder. */
'use strict';
const Compass=(()=>{
 const arrows=['→','↘','↓','↙','←','↖','↑','↗'];
 function reading(point){
  const dx=point.x-(player.x+player.w/2),dy=point.y-(player.y+player.h);
  const near=Math.abs(dx)<90&&Math.abs(dy)<85;
  const sector=(Math.round(Math.atan2(dy,dx)/(Math.PI/4))+8)%8;
  return {near,sector,arrow:near?'✓':arrows[sector],label:near?'compass.near':'compass.direction.'+sector};
 }
 function update(objective){
  const box=$('compass');
  box.hidden=!player||!Merchant.stock('compass')||Prologue.active||$('quest').hidden||state==='menu'||state==='won'||state==='help'&&helpOrigin==='menu'||DevTools.menuBackground;
  if(box.hidden)return;
  objective??=nextObjective();
  $('compassLabel').textContent=I18n.t('item.compass');
  box.title=I18n.t('inventory.description.compass');
  const target=$('compassTarget'),direction=$('compassDirection'),arrow=$('compassArrow');
  target.hidden=objective.compass===false;
  if(target.hidden){target.textContent='';direction.textContent=I18n.t('compass.idle');arrow.textContent='—';return;}
  const bearing=reading(objective.point);
  target.textContent=I18n.format('compass.target',[I18n.t(objective.name)]);
  direction.textContent=I18n.t(bearing.label);arrow.textContent=bearing.arrow;
 }
 return Object.freeze({update,reading});
})();


/* slayer-dialog.js */
/* A deliberately unhinted incantation; the encounter starts only after confirmation. */
const SlayerDialog=(()=>{
 let initialized=false,returnFocus=null,encounter=null,revision=0,hasError=false,warningOpen=false;
 const modal=()=>$('slayerSpell');
 const clearKeys=()=>{keys.clear();pressed.clear();};
 function render(){
  $('slayerSpellTitle').textContent=I18n.t('slayer.name');
  $('slayerSpellText').textContent=I18n.t('slayer.epitaph');
  $('slayerSpellLabel').textContent=I18n.t('slayer.incantation');
  $('slayerSpellSubmit').textContent=I18n.t('slayer.speak');
  $('closeSlayerSpell').textContent=I18n.t('inventory.close');
  $('slayerSpellMessage').textContent=hasError?I18n.t('slayer.silent'):'';
 }
 function clearInput(){
  $('slayerSpellInput').value='';
  $('slayerSpellInput').removeAttribute?.('aria-invalid');
  $('slayerSpellMessage').textContent='';hasError=false;
 }
 function restoreFocus(){
  if(returnFocus?.isConnected&&typeof returnFocus.focus==='function')returnFocus.focus();
  else $('pauseButton')?.focus();
  returnFocus=null;
 }
 function open(e){
  if(state!=='play'||level!==yomi||!e||e.dead||e.active||!enemies.includes(e))return false;
  init();revision++;encounter=e;returnFocus=document.activeElement;
  clearInput();render();clearKeys();state='slayerSpell';modal().hidden=false;
  $('slayerSpellInput').focus();return true;
 }
 function close(){
  if(state!=='slayerSpell')return false;
  revision++;encounter=null;modal().hidden=true;clearInput();clearKeys();state='play';restoreFocus();return true;
 }
 // Also invalidates an already-open warning when main menu/travel cancels an encounter.
 function cancel(){
  const wasOpen=state==='slayerSpell';
  revision++;encounter=null;modal().hidden=true;clearInput();clearKeys();returnFocus=null;
  if(warningOpen){$('dialog').hidden=true;$('dialogOk').onclick=null;if(state==='dialog')state='play';warningOpen=false;}
  $('dialog').classList.remove('slayer-warning');
  if(wasOpen)state='play';
 }
 function submit(event){
  event.preventDefault();
  if(state!=='slayerSpell')return;
  if($('slayerSpellInput').value.trim().toLowerCase()!=='iddqd'){
   hasError=true;render();$('slayerSpellInput').setAttribute('aria-invalid','true');$('slayerSpellInput').focus();return;
  }
  const e=encounter,origin=level;
  close();const expected=revision;
  warningOpen=true;$('dialog').classList.add('slayer-warning');
  story('slayer.name','slayer.warning','slayer.epitaph',()=>{
   warningOpen=false;
   $('dialog').classList.remove('slayer-warning');
   if(expected!==revision||state!=='play'||level!==origin||level!==yomi||!enemies.includes(e)||e.dead||e.active)return;
   if(DoomSlayer.start(e)&&!flags[1].includes('slayerSummoned')){flags[1].push('slayerSummoned');persist();}
  });
 }
 function keydown(event){
  if(state!=='slayerSpell')return;
  // Stop all typed letters before the window-level gameplay hotkeys see them.
  event.stopPropagation();
  const key=Bindings.normalize(event.code==='Space'?' ':event.key);
  const target=event.target||document.activeElement,editing=target===$('slayerSpellInput')||target?.matches?.('input,textarea,[contenteditable="true"]');
  if(key==='escape'||!editing&&Bindings.read('pause').includes(key)){
   event.preventDefault();if(!event.repeat)close();return;
  }
  if(key!=='tab')return;
  const nodes=[...modal().querySelectorAll('input:not([disabled]),button:not([disabled])')].filter(node=>!node.hidden&&node.getClientRects().length);
  const first=nodes[0],last=nodes[nodes.length-1];
  if(!first)return;
  if(event.shiftKey&&(document.activeElement===first||!nodes.includes(document.activeElement))){event.preventDefault();last.focus();}
  else if(!event.shiftKey&&(document.activeElement===last||!nodes.includes(document.activeElement))){event.preventDefault();first.focus();}
 }
 function init(){
  if(initialized)return;initialized=true;
  $('slayerSpellForm').addEventListener('submit',submit);
  $('closeSlayerSpell').addEventListener('click',close);
  $('slayerSpellInput').addEventListener('input',()=>{if(hasError){hasError=false;render();$('slayerSpellInput').removeAttribute?.('aria-invalid');}});
  modal().addEventListener('keydown',keydown);
  modal().addEventListener('keyup',event=>{if(state==='slayerSpell')event.stopPropagation();});
  I18n.onChange(()=>{if(state==='slayerSpell')render();});
 }
 return Object.freeze({init,open,close,cancel});
})();


/* bug-report.js */
/* A public Tally form; never exports saves or raw browser/session data. */
'use strict';
const BugReport=(()=>{
 const endpoint='https://tally.so/r/8Nojjr';
 const areas=new Set(['menu','dream','japan','yomi','heaven','council','forestCamp']);
 function browserName(){
  const agent=navigator.userAgent||'';
  for(const [pattern,name] of [[/(?:Edg|EdgA|EdgiOS)\/(\d+)/,'Edge'],[/(?:Firefox|FxiOS)\/(\d+)/,'Firefox'],[/(?:OPR|OPiOS)\/(\d+)/,'Opera'],[/(?:Chrome|CriOS)\/(\d+)/,'Chrome'],[/Version\/(\d+).*Safari\//,'Safari']]){
   const match=agent.match(pattern);if(match)return name+' '+match[1];
  }
  return I18n.t('bugReport.unknown');
 }
 function createURL(area='menu'){
  const url=new URL(endpoint),safeArea=areas.has(area)?area:'menu';
  const fields={
   version:GAME_RELEASE.version,language:I18n.locale,area:I18n.t('bugReport.area.'+safeArea),browser:browserName(),
   viewport:`${Math.round(innerWidth)} × ${Math.round(innerHeight)}`,pixel_ratio:Number(devicePixelRatio||1).toFixed(2),
   input:I18n.t('bugReport.pointer')
  };
  for(const [key,value] of Object.entries(fields))url.searchParams.set(key,value);
  return url.href;
 }
 function init(currentArea){
  const refreshers=[];
  for(const link of document.querySelectorAll('[data-bug-report]')){
   const refresh=()=>{
    link.href=createURL(link.dataset.bugReport==='menu'?'menu':currentArea());
    link.setAttribute('aria-label',I18n.t('bugReport.label'));
    link.title=I18n.t('bugReport.hint');
   };
   refresh();refreshers.push(refresh);
   for(const event of ['focus','pointerdown','click'])link.addEventListener(event,refresh);
  }
  I18n.onChange(()=>refreshers.forEach(refresh=>refresh()));
 }
 return Object.freeze({createURL,init});
})();


/* dev-session.js */
/* In-memory developer runs never replace normal progression or stored records. */
'use strict';
const DevSession=(()=>{
 let active=false,normalSave=null,initialized=false;
 const endHandlers=new Set();
 const clone=value=>value?JSON.parse(JSON.stringify(value)):null;
 const ready=()=>storageReady&&loadingReady&&Visuals.loaded===Visuals.total&&!Visuals.failures.length;
 function refresh(){
  const badge=$('devTestNotice');badge.hidden=!active;badge.textContent=I18n.t('dev.session.active');
  $('devSessionInfo').textContent=I18n.t('dev.session.info');
 }
 function begin(){
  if(state!=='developer'||!DevTools.isOpen||!ready())return false;
  if(active)return true;
  normalSave=clone(saved);active=true;
  if(DevTools.menuBackground){
   const old=normalSave;
   abilities=old?[...old.abilities]:[false,false];defeated=old?[...old.defeated]:levels.map(()=>false);
   flags=old?old.flags.map(f=>[...f]):levels.map(()=>[]);visitedRests=old?old.visitedRests.map(f=>[...f]):levels.map(()=>[]);
   shards=old?old.shards:0;coins=old?.coins??0;meatCount=old?.meatCount??0;teaCount=old?.teaCount??0;quickHeal=old?.quickHeal??'roastMeat';progression=normalizeProgression(old?.progression,flags);
   Prologue.stop();enterRealm(0);
  }else if(Prologue.active){Prologue.stop();enterRealm(0);}
  $('menu').hidden=true;$('pause').hidden=true;showHUD(true);DevTools.setReturnState('play');
  refresh();updateHUD();return true;
 }
 function end(){
  if(!active)return false;
  active=false;saved=clone(normalSave);normalSave=null;
  for(const handler of endHandlers)handler();
  if(DevTools.isOpen)DevTools.close();
  refresh();mainMenu();return true;
 }
 function init(){
  if(initialized)return;initialized=true;
  DevTools.register({id:'test-start',labelKey:'dev.session.start',available:()=>!active&&ready(),run:begin});
  DevTools.register({id:'test-end',labelKey:'dev.session.end',available:()=>active,run:end});
  Visuals.ready.then(()=>{if(DevTools.isOpen)DevTools.refresh();});
  I18n.onChange(refresh);refresh();
 }
 return Object.freeze({begin,end,init,refresh,onEnd(handler){endHandlers.add(handler);},get active(){return active;},get ready(){return ready();}});
})();


/* dev-tools.js */
/* Developer utilities, reached outside the player menus. */
'use strict';
const DevTools=(()=>{
 const tools=new Map();
 let initialized=false,opened=false,session=0,render=0,origin='menu',returnFocus=null,message='';
 let inertSiblings=[],overlays=[];
 const overlayIds=['menu','pause','inventory','map','training','help','dialog','shop','slayerSpell'];
 const node=id=>document.getElementById(id);
 function text(id,key){node(id).textContent=I18n.t(key);}
 function refresh(){
  if(!initialized)return;
  for(const [id,key] of Object.entries({devEyebrow:'dev.eyebrow',devTitle:'dev.title',devIntro:'dev.intro',devClose:'dev.close',devEmpty:'dev.empty'}))text(id,key);
  node('devVersion').textContent=I18n.format('dev.version',[GAME_RELEASE.version]);
  node('devStatus').textContent=message?I18n.t(message):'';node('devStatus').hidden=!message;
  const focusId=document.activeElement?.id,list=node('devToolsList');list.replaceChildren();
  const currentSession=session,currentRender=++render;
  if(opened)for(const tool of tools.values()){
   const valid=()=>opened&&currentSession===session&&currentRender===render&&state==='developer'&&(!tool.available||tool.available());
   const controls=[],fields=tool.fields?.()||[];
   const group=fields.length?document.createElement('section'):list;
   if(fields.length){group.className='dev-tool-fields';list.append(group);}
   for(const field of fields){
    const label=document.createElement('label'),input=document.createElement(field.type==='select'?'select':'input');
    input.id='dev-'+tool.id+'-'+field.id;label.htmlFor=input.id;label.textContent=I18n.t(field.labelKey);
    if(field.type==='select')for(const entry of field.options){const option=document.createElement('option');option.value=String(entry.value);option.textContent=I18n.t(entry.label);input.append(option);}
    else{input.type='number';input.min=field.min;input.max=field.max;input.step=1;}
    input.value=String(field.value);input.disabled=!!tool.available&&!tool.available();
    input.onchange=()=>{if(!valid())return;if(field.change){field.change(input.value);refresh();}};
    controls.push([field.id,input]);group.append(label);group.append(input);
   }
   const button=document.createElement('button');button.type='button';button.textContent=I18n.t(tool.labelKey);
   button.id='dev-tool-'+tool.id;
   if(tool.toggled){const on=!!tool.toggled();button.setAttribute('aria-pressed',String(on));button.textContent+=' · '+I18n.t(on?'dev.on':'dev.off');}
   button.disabled=!!tool.available&&!tool.available();
   button.onclick=()=>{
    if(!valid())return;
    try{const result=tool.run(Object.fromEntries(controls.map(([id,input])=>[id,input.value])));message=typeof result==='string'?result:result===false?'dev.invalid':result===true?'dev.applied':'';refresh();}catch{message='dev.toolError';refresh();}
   };
   group.append(button);
  }
  node('devEmpty').hidden=tools.size>0;
  if(opened&&focusId){const previous=node(focusId);if(previous&&!previous.disabled&&previous.getClientRects().length)previous.focus();}
 }
 function register(tool){
  if(!tool||!/^[-a-z0-9]+$/.test(tool.id)||typeof tool.labelKey!=='string'||typeof tool.run!=='function'||tool.available!==undefined&&typeof tool.available!=='function'||tools.has(tool.id))throw Error('Invalid developer tool registration');
  tools.set(tool.id,Object.freeze({...tool}));if(opened)refresh();
 }
 function open(){
  if(!initialized||resolutionBlocked)return false;if(opened)return true;
  if(!['menu','play','pause','inventory','map','training','help','dialog','shop','slayerSpell','won'].includes(state))return false;
  origin=state;returnFocus=document.activeElement;opened=true;session++;message='';state='developer';keys.clear();pressed.clear();
  overlays=overlayIds.map(id=>[node(id),node(id).hidden]);
  for(const [overlay] of overlays)overlay.hidden=true;
  inertSiblings=[...node('game').children].filter(child=>child!==node('devPanel')).map(child=>[child,child.inert]);
  for(const [child] of inertSiblings)child.inert=true;
  node('devPanel').hidden=false;node('devPanel').scrollTop=0;refresh();node('devClose').focus();return true;
 }
 function close(){
  if(!opened)return false;opened=false;session++;message='';refresh();node('devPanel').hidden=true;
  for(const [child,wasInert] of inertSiblings)child.inert=wasInert;inertSiblings=[];
  for(const [overlay,wasHidden] of overlays)overlay.hidden=wasHidden;overlays=[];
  state=origin;keys.clear();pressed.clear();
  if(origin==='inventory')Inventory.render();
  if(origin==='shop')Merchant.render();
  if(window.location?.hash==='#devtools')window.history.replaceState(null,'',window.location.pathname+window.location.search);
  if(returnFocus?.isConnected&&returnFocus.matches?.('button,a[href],input,select,textarea,summary,[tabindex]')&&!returnFocus.disabled&&!returnFocus.closest('[inert]')&&returnFocus.getClientRects().length)returnFocus.focus();
  else node(({menu:'startButton',pause:'resumeButton',inventory:'closeInventory',map:'closeMap',training:'closeTraining',help:'helpTitle',dialog:'dialogOk',won:'dialogOk',shop:'closeShop'})[origin]||'pauseButton').focus();
  return true;
 }
 function init(){
  if(initialized)return;initialized=true;
  node('devClose').onclick=close;
  node('devPanel').addEventListener('keydown',event=>{
   if(!opened)return;
   if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close();return;}
   if(event.key!=='Tab')return;
   const controls=[...node('devPanel').querySelectorAll('input:not([disabled]),select:not([disabled]),button:not([disabled])')].filter(control=>control.getClientRects().length);
   if(!controls.length)return;const first=controls[0],last=controls[controls.length-1];
   if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
   else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
  });
  const fromHash=()=>{if(window.location?.hash==='#devtools')open();};
  window.addEventListener('hashchange',fromHash);I18n.onChange(refresh);refresh();fromHash();
 }
 function setReturnState(value){
  if(!opened||!['menu','play','pause'].includes(value))return false;
  origin=value;overlays=overlays.map(([overlay])=>[overlay,overlay!==node(value)]);
  if(typeof captureAction!=='undefined')captureAction=null;
  returnFocus=null;return true;
 }
 return Object.freeze({init,open,close,register,refresh,setReturnState,get isOpen(){return opened;},get returnState(){return origin;},get menuBackground(){return opened&&(origin==='menu'||origin==='help'&&helpOrigin==='menu');}});
})();


/* dev-boss.js */
/* Encounter replays are restricted to the in-memory developer character. */
'use strict';
const DevBoss=(()=>{
 let encounter='main';
 const available=()=>DevSession.active&&!!player&&(Prologue.active||level===levels[realm]);
 const encounters=()=>[{id:'main',name:Prologue.active?'prologue.boss':realms[realm].boss},
  ...(Prologue.active?[]:level.enemies.filter(spec=>spec.miniboss).map(spec=>({id:spec.id,name:spec.name})))];
 function fields(){
  const options=encounters();if(!options.some(entry=>entry.id===encounter))encounter='main';
  return [{id:'encounter',type:'select',labelKey:'dev.boss',value:encounter,options:options.map(entry=>({value:entry.id,label:entry.name})),change:value=>{if(encounters().some(entry=>entry.id===value))encounter=value;}}];
 }
 function revive(values){
  if(!available()||state!=='developer'||!DevTools.isOpen)return false;
  const target=values?.encounter??'main';if(!encounters().some(entry=>entry.id===target))return false;
  if(target!=='main')return reviveMiniboss(target);
  if(Prologue.active){Prologue.start();state='developer';DevTools.setReturnState('play');return true;}
  clearEncounterEffects();defeated[realm]=false;resetBossBattle();
  const rest=level.rests.find(r=>r.id===level.arena.restId)||level.rests[0];
  checkpoint={...rest};initPlayer(rest);particles=[];projectiles=[];drops=[];visits.delete('boss');
  const a=level.arena;
  // Choose the arena floor on the approach side, with no teleport into the boss.
  const floor=platforms.find(p=>!p.broken&&Math.abs(p.y-a.y)<2&&p.x<=a.x+70&&p.x+p.w>=a.x+70);
  if(floor)initPlayer({x:a.x+70,y:floor.y});
  bossStarted=true;resetCamera();updateHUD();DevTools.setReturnState('play');return true;
 }
 function reviveMiniboss(id){
  const index=level.enemies.findIndex(spec=>spec.id===id&&spec.miniboss);if(index<0)return false;
  const replay=createEnemy(level.enemies[index],index),a=replay.arena;
  const floor=platforms.find(p=>!p.broken&&Math.abs(p.y-a.y)<2&&p.x<=a.x+70&&p.x+p.w>=a.x+70);
  if(!floor)return false;
  clearEncounterEffects();if(!boss.dead)resetBossBattle();
  resetMinibosses();projectiles=[];
  // Preserve permanent guardian/reward flags: only this in-memory encounter is replaced.
  if(DoomSlayer.is(replay))replay.replay=true;
  resetMiniboss(replay);replay.dead=false;
  if(DoomSlayer.is(replay))DoomSlayer.start(replay);else replay.active=true;
  const existing=enemies.findIndex(enemy=>enemy.id===id);if(existing<0)enemies.push(replay);else enemies[existing]=replay;
  initPlayer({x:a.x+70,y:floor.y});particles=[];drops=[];keys.clear();pressed.clear();
  resetCamera();updateHUD();DevTools.setReturnState('play');return true;
 }
 function init(){DevTools.register({id:'boss-revive',labelKey:'dev.boss',available,fields,run:revive});}
 return Object.freeze({init,revive});
})();


/* dev-teleport.js */
'use strict';
const DevTeleport=(()=>{
 let destination='0',restId=levels[0].rests[0].id;
 const available=()=>DevSession.active;
 // The picker and executor share the same catalogue, including side areas
 // that deliberately are not additional realms in the main levels array.
 const destinations=()=>[
  ...levels.map((map,n)=>({id:String(n),label:realms[n].name,map,enter:rest=>{Prologue.stop();enterRealm(n,rest);return true;}})),
  {id:'forestCamp',label:'camp.name',map:forestCamp,enter:()=>{Prologue.stop();return enterForestCamp({save:false,atShrine:true});}},
  {id:'dream',label:'prologue.label',rests:[{id:'dream',name:'prologue.place'}],enter:()=>{Prologue.start();return true;}}
 ];
 const restsFor=target=>target.map?.rests||target.rests;
 function fields(){
  const catalogue=destinations(),target=catalogue.find(entry=>entry.id===destination),rests=restsFor(target);
  if(!rests.some(r=>r.id===restId))restId=rests[0].id;
  return [
   {id:'realm',type:'select',labelKey:'dev.realm',value:destination,options:catalogue.map(entry=>({value:entry.id,label:entry.label})),change:value=>{const next=destinations().find(entry=>entry.id===value);if(next){destination=value;restId=restsFor(next)[0].id;}}},
   {id:'rest',type:'select',labelKey:'dev.arrival',value:restId,options:rests.map(r=>({value:r.id,label:r.name})),change:value=>{restId=value;}}
  ];
 }
 function teleport(values){
  if(!available()||state!=='developer'||!DevTools.isOpen)return false;
  const target=destinations().find(entry=>entry.id===String(values?.realm));
  if(!target)return false;
  const rest=restsFor(target).find(r=>r.id===values?.rest);
  if(!rest||target.map&&!target.map.platforms.some(p=>!p.broken&&Math.abs(p.y-rest.y)<2&&rest.x>p.x&&rest.x<p.x+p.w))return false;
  if(!target.enter(rest))return false;
  if(target.map&&!visitedRests[realm].includes(rest.id))visitedRests[realm].push(rest.id);
  state='developer';DevTools.setReturnState('play');keys.clear();pressed.clear();context=null;$('prompt').hidden=true;showHUD(true);updateHUD();return true;
 }
 function init(){DevTools.register({id:'teleport',labelKey:'dev.teleport',available,fields,run:teleport});}
 return Object.freeze({init,teleport});
})();


/* dev-level.js */
'use strict';
const DevLevel=(()=>{
 const available=()=>DevSession.active&&!!player;
 function setLevel(values){
  if(!available()||state!=='developer'||!DevTools.isOpen)return false;
  const raw=String(values?.level??'');
  if(!/^\d+$/.test(raw))return false;
  const target=Number(raw);if(!Number.isSafeInteger(target)||target<1||target>LEVEL_LIMIT)return false;
  let totalXp=0;for(let n=1;n<target;n++)totalXp+=xpForLevel(n);
  // Preserve affordable allocations and refund the remainder through the
  // same budget normalization used by ordinary progression.
  progression=normalizeProgression({level:target,xp:0,totalXp,stats:progression.stats},flags);
  player.maxHp=momoStats().maxHp;player.hp=Math.max(1,Math.min(player.hp,player.maxHp));
  updateHUD();return true;
 }
 function init(){DevTools.register({id:'player-level',labelKey:'dev.level.set',available,
  fields:()=>[{id:'level',type:'number',labelKey:'dev.level',value:player?progression.level:1,min:1,max:LEVEL_LIMIT}],run:setLevel});}
 return Object.freeze({init,setLevel});
})();


/* dev-items.js */
'use strict';
const DevItems=(()=>{
 let selected=Object.keys(ART_INVENTORY.items)[0],amount=100;
 const available=()=>DevSession.active&&!!player;
 function add(values){
  if(!available()||state!=='developer'||!DevTools.isOpen)return false;
  const id=values?.item;
  if(typeof id!=='string'||!Object.hasOwn(ART_INVENTORY.items,id))return false;
  const item=ART_INVENTORY.items[id];
  if(item.stack){if(!Merchant.addStock(id))return false;updateHUD();return true;}
  if(flags[item.realm].includes(id)||item.consumedBy&&flags[item.consumedBy.realm].includes(item.consumedBy.id))return 'dev.item.owned';
  flags[item.realm].push(id);updateHUD();return true;
 }
 function addCoins(values){
  if(!available()||state!=='developer'||!DevTools.isOpen)return false;
  const raw=String(values?.amount??'');if(!/^\d+$/.test(raw))return false;
  const count=Number(raw);
  if(!Number.isSafeInteger(count)||count<1||count>Number.MAX_SAFE_INTEGER-coins)return false;
  Merchant.award(count);amount=count;updateHUD();return true;
 }
 function init(){
  DevTools.register({id:'inventory-item',labelKey:'dev.item.add',available,
   fields:()=>[{id:'item',type:'select',labelKey:'dev.item',value:selected,options:Object.entries(ART_INVENTORY.items).map(([value,item])=>({value,label:item.name})),change:value=>{if(Object.hasOwn(ART_INVENTORY.items,value))selected=value;}}],run:add});
  DevTools.register({id:'coins',labelKey:'dev.coins.add',available,
   fields:()=>[{id:'amount',type:'number',labelKey:'dev.amount',value:amount,min:1,max:Number.MAX_SAFE_INTEGER}],run:addCoins});
 }
 return Object.freeze({init,add,addCoins});
})();


